import{d as e,i as t}from"./index-BVdLvPw-.js";import{t as n}from"./BlogPost-BCN0DswP.js";var r=t();function i(){return(0,r.jsxs)(n,{path:`/blog-copilot-readiness`,geoNote:!0,children:[(0,r.jsx)(`p`,{children:`Microsoft 365 Copilot can draft documents, summarise meetings and answer questions using your organisation's data. Because it respects existing permissions, it can surface anything a user already has access to, including files that were shared too widely years ago.`}),(0,r.jsx)(`p`,{children:`That is the main thing to understand before you buy licences. Copilot does not create new access. It makes existing access easier to use. If a salary spreadsheet sits in a folder the whole company can open, nobody may have noticed it for years. Once Copilot is switched on, a simple question about pay could bring it straight to the surface.`}),(0,r.jsx)(`h2`,{children:`How Copilot uses your data`}),(0,r.jsx)(`p`,{children:`Microsoft 365 Copilot works with the emails, chats, meetings and files in your Microsoft 365 tenant. When someone asks a question, it searches only the content that person is already allowed to see, then uses that content to write its answer.`}),(0,r.jsx)(`p`,{children:`Microsoft says prompts and responses stay within the Microsoft 365 service boundary and are not used to train its foundation models. Read Microsoft’s current privacy documentation for the detail. The bigger risk for most small businesses is not Microsoft. It is their own sharing settings.`}),(0,r.jsxs)(`p`,{children:[`It also helps to know the difference between Copilot Chat, which Microsoft 365 users can use for web-based questions, and the full Microsoft 365 Copilot, which needs a paid licence and can work with your business data. Our `,(0,r.jsx)(e,{to:`/blog-microsoft-365-plans-compared`,children:`comparison of Microsoft 365 plans`}),` explains the licensing options.`]}),(0,r.jsx)(`h2`,{children:`Five steps before you switch it on`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsx)(`li`,{children:`Review who can access sensitive SharePoint sites and Teams.`}),(0,r.jsx)(`li`,{children:`Remove 'anyone with the link' sharing where it isn't needed.`}),(0,r.jsx)(`li`,{children:`Apply sensitivity labels to confidential documents.`}),(0,r.jsx)(`li`,{children:`Archive old, duplicate and out-of-date files.`}),(0,r.jsx)(`li`,{children:`Choose a pilot group and agree what success looks like.`})]}),(0,r.jsx)(`h3`,{children:`1. Review access to sensitive sites`}),(0,r.jsx)(`p`,{children:`Start with the places most likely to hold sensitive information: HR, finance, payroll, legal, board papers and client records. Check who is a member or owner of each SharePoint site and Team. Watch for groups such as "Everyone" or "Everyone except external users", which give access to the whole organisation.`}),(0,r.jsx)(`h3`,{children:`2. Tighten sharing links`}),(0,r.jsx)(`p`,{children:`Links that anyone can open, and links shared with the whole organisation, are a common source of oversharing. Change the default link type in SharePoint and OneDrive to people with existing access or specific people, and clean up old links on sensitive files.`}),(0,r.jsx)(`p`,{children:`Microsoft includes some SharePoint Advanced Management tools with Microsoft 365 Copilot licences, such as reports on oversharing and the option to hide selected sites from Copilot while you review them. Check which tools come with your licence.`}),(0,r.jsx)(`h3`,{children:`3. Label confidential documents`}),(0,r.jsx)(`p`,{children:`Sensitivity labels mark a document as, for example, Confidential, and can add encryption or restrict who can open it. Copilot respects these protections. Start with a small set of labels that people will actually use, rather than a long list that nobody understands.`}),(0,r.jsx)(`h3`,{children:`4. Archive what you no longer need`}),(0,r.jsx)(`p`,{children:`Old drafts, duplicate copies and outdated policies can lead Copilot to give confident answers based on the wrong version. Archiving or deleting stale content improves both security and answer quality. Agree retention rules first, so you don't delete records you are required to keep.`}),(0,r.jsx)(`h3`,{children:`5. Run a pilot`}),(0,r.jsx)(`p`,{children:`Pick five to fifteen people from different roles who are curious and willing to give honest feedback. Agree in advance what you will measure, such as time saved on meeting notes or first drafts, and review results after a few weeks before buying more licences.`}),(0,r.jsx)(`h2`,{children:`Pick the right first use cases`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Summarising long email threads and meetings.`}),(0,r.jsx)(`li`,{children:`First drafts of proposals and policies.`}),(0,r.jsx)(`li`,{children:`Finding information across Teams, Outlook and SharePoint.`})]}),(0,r.jsx)(`p`,{children:`For example, a project manager could ask Copilot in Teams for a summary of decisions and action items after a client meeting, or a sales lead could ask it to draft a proposal from a previous one and the latest pricing notes. Avoid starting with tasks where an error is costly, such as legal advice or financial figures that go straight to clients.`}),(0,r.jsx)(`h2`,{children:`Train people, not just licences`}),(0,r.jsx)(`p`,{children:`Short, practical sessions on writing good prompts and checking outputs make the difference between a novelty and a real productivity gain.`}),(0,r.jsx)(`p`,{children:`A good prompt gives Copilot a goal, context, the sources to use and the format you want. Compare "write an email" with "draft a short, friendly email to the client confirming the new delivery date, based on yesterday's meeting notes". Staff also need to know that Copilot can be wrong, so a person must check facts, numbers and tone before anything is sent.`}),(0,r.jsx)(`h2`,{children:`Common mistakes`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Buying licences for everyone before tidying permissions.`}),(0,r.jsx)(`li`,{children:`Treating Copilot answers as final without checking them.`}),(0,r.jsx)(`li`,{children:`Rolling it out with no training or success measures.`}),(0,r.jsx)(`li`,{children:`Ignoring basic security such as multi-factor authentication. A compromised account with Copilot can find information faster.`})]}),(0,r.jsx)(`h3`,{children:`A quick readiness checklist`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Sensitive sites reviewed and access tightened.`}),(0,r.jsx)(`li`,{children:`Organisation-wide and anonymous links cleaned up.`}),(0,r.jsx)(`li`,{children:`Sensitivity labels agreed and published.`}),(0,r.jsx)(`li`,{children:`Multi-factor authentication on for every user.`}),(0,r.jsx)(`li`,{children:`Pilot group, use cases and measures agreed.`})]}),(0,r.jsx)(`h2`,{children:`Frequently asked questions`}),(0,r.jsx)(`h3`,{children:`Can Copilot see files a user cannot open?`}),(0,r.jsx)(`p`,{children:`No. Copilot works within each user's existing permissions. The risk is that those permissions are often wider than people realise.`}),(0,r.jsx)(`h3`,{children:`Do we need Business Premium to use Copilot?`}),(0,r.jsxs)(`p`,{children:[`No. Copilot can be added to Business Basic, Standard or Premium. Premium adds security tools, such as device management and sign-in controls, that make a rollout safer. See our `,(0,r.jsx)(e,{to:`/microsoft-licensing`,children:`Microsoft licensing service`}),` for advice on the right mix.`]}),(0,r.jsx)(`h3`,{children:`How long does it take to get ready?`}),(0,r.jsx)(`p`,{children:`It depends on how much content you have and how tidy it is. A small business with well-organised SharePoint may only need a short review, while years of uncontrolled sharing takes longer.`}),(0,r.jsx)(`h3`,{children:`Is our data safe with Copilot?`}),(0,r.jsxs)(`p`,{children:[`Microsoft provides enterprise data protections, but your own settings matter most. Pairing a Copilot rollout with a `,(0,r.jsx)(e,{to:`/cybersecurity`,children:`cybersecurity review`}),` is a sensible step.`]}),(0,r.jsxs)(`p`,{children:[`We can review your Microsoft 365 permissions and plan a Copilot pilot. See `,(0,r.jsx)(e,{to:`/microsoft-development`,children:`Microsoft Product Development`}),`.`]})]})}export{i as default};